import pandas as pd

def find_best_candidates(candidates: pd.DataFrame, projects: pd.DataFrame) -> pd.DataFrame:
    if candidates.empty or projects.empty:
        return pd.DataFrame(columns=['project_id', 'candidate_id', 'score'])

    req_counts = projects.groupby('project_id')['skill'].count().reset_index(name='req_count')
    merged = projects.merge(candidates, on='skill')

    def score_diff(row):
        if row['proficiency'] > row['importance']:
            return 10
        elif row['proficiency'] < row['importance']:
            return -5
        return 0

    merged['pts'] = merged.apply(score_diff, axis=1)

    grouped = merged.groupby(['project_id', 'candidate_id']).agg(
        matched_skills=('skill', 'count'),
        total_pts=('pts', 'sum')
    ).reset_index()

    eligible = grouped.merge(req_counts, on='project_id')
    eligible = eligible[eligible['matched_skills'] == eligible['req_count']].copy()
    if eligible.empty:
        return pd.DataFrame(columns=['project_id', 'candidate_id', 'score'])

    eligible['score'] = 100 + eligible['total_pts']

    # Pick top candidate per project
    eligible = eligible.sort_values(by=['project_id', 'score', 'candidate_id'], ascending=[True, False, True])
    best = eligible.drop_duplicates(subset=['project_id'], keep='first')

    res = best[['project_id', 'candidate_id', 'score']]
    return res.sort_values(by='project_id', ascending=True)
